class Solution {
  public List<List<Integer>> supersequences(String[] words) {
    int[] id = new int[26];
    java.util.Arrays.fill(id, -1);
    int m = 0;
    int[] letters = new int[26];
    for (String w : words) {
      for (int i = 0; i < 2; i++) {
        int c = w.charAt(i) - 'a';
        if (id[c] < 0) {
          letters[m] = c;
          id[c] = m++;
        }
      }
    }
    int forced = 0;
    int[] pred = new int[m];
    for (String w : words) {
      int a = id[w.charAt(0) - 'a'], b = id[w.charAt(1) - 'a'];
      if (a == b) forced |= 1 << a;
      else pred[b] |= 1 << a;
    }
    int full = (1 << m) - 1, bestSize = Integer.MAX_VALUE;
    List<Integer> best = new ArrayList<>();
    for (int mask = forced; mask <= full; mask = (mask + 1) | forced) {
      int size = Integer.bitCount(mask);
      if (size > bestSize) continue;
      int remaining = full & ~mask;
      boolean progress = true;
      while (remaining != 0 && progress) {
        progress = false;
        for (int u = 0; u < m; u++) {
          if ((remaining >> u & 1) != 0 && (pred[u] & remaining) == 0) {
            remaining &= ~(1 << u);
            progress = true;
          }
        }
      }
      if (remaining != 0) continue;
      if (size < bestSize) {
        bestSize = size;
        best.clear();
      }
      best.add(mask);
    }
    List<List<Integer>> res = new ArrayList<>();
    for (int mask : best) {
      Integer[] f = new Integer[26];
      java.util.Arrays.fill(f, 0);
      for (int u = 0; u < m; u++) f[letters[u]] = (mask >> u & 1) != 0 ? 2 : 1;
      res.add(java.util.Arrays.asList(f));
    }
    return res;
  }
}
